package com.smarthub.plus;
import android.os.Bundle;
import android.text.InputType;
import android.view.View;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;
/** Direct provider settings. Blank fields preserve encrypted credentials already on this TV. */
public final class ProviderSetupActivity extends HubActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private EditText open,sub,tmdb;private TextView status;private Button save;private volatile boolean closed;
 @Override public void onCreate(Bundle state){super.onCreate(state);ProviderSecrets.clearLegacy(this);LinearLayout body=page(tx("مصادر الصور والترجمة","Artwork and subtitle providers"));note(body,tx("TMDB هو المصدر الأساسي للصور عند حفظ مفتاح صالح. يتصل التلفزيون بالمزودين مباشرة عبر HTTPS؛ لا يحتاج إلى خادم كمبيوتر. تُحفظ المفاتيح مشفّرة في Android Keystore ولا تُضمّن داخل APK. اترك الحقل فارغاً للاحتفاظ بمفتاحه المحفوظ.","TMDB is the primary artwork source when a valid key is saved. This TV connects directly over HTTPS without a computer server. Android Keystore protects your keys; they are never embedded in the APK. Blank fields preserve saved credentials."));note(body,"This product uses the TMDB API but is not endorsed or certified by TMDB.");tmdb=field(body,"TMDB API Key / API Read Access Token","");open=field(body,"OpenSubtitles API Key","");sub=field(body,"Subsource API Key","");for(EditText input:new EditText[]{tmdb,open,sub}){input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);input.setTextDirection(View.TEXT_DIRECTION_LTR);}note(body,tx("اختبار OpenSubtitles يتحقق من بحث وتنزيل فعلي وقد يستهلك تنزيلاً من الحصة. لا ترسل المفاتيح في المحادثة.","OpenSubtitles validation performs a real search and download and may use one download allowance. Do not post keys in the chat."));action(body,tx("إصلاح الشعارات والبوسترات · TVmaze وTheSportsDB وWikimedia Commons","Fix logos and posters · TVmaze, TheSportsDB and Wikimedia Commons"),()->startActivity(new android.content.Intent(this,ArtworkSourcesActivity.class)));status=text("",16,false);body.addView(status);save=action(body,tx("اختبار وحفظ المفاتيح","Test and save keys"),this::validate);try{ProviderSecrets s=ProviderSecrets.read(this);status.setText("TMDB: "+(s.tmdb.isEmpty()?"—":"✓")+" · OpenSubtitles: "+(s.opensubtitles.isEmpty()?"—":"✓")+" · Subsource: "+(s.subsource.isEmpty()?"—":"✓"));}catch(Exception ignored){}}
 private void validate(){String os=open.getText().toString().trim(),ss=sub.getText().toString().trim(),tk=tmdb.getText().toString().trim();save.setEnabled(false);status.setText(tx("اختبار الاتصال المباشر…","Testing direct connections…"));io.execute(()->{try{ProviderSecrets old=ProviderSecrets.read(this);String validOs=old.opensubtitles,validSub=old.subsource,validTmdb=old.tmdb;List<String> messages=new ArrayList<>();if(!tk.isEmpty())try{new TmdbProvider(this,tk).validate();validTmdb=tk;messages.add("TMDB: ✓ "+tx("تم التحقق والحفظ","Verified and saved"));prefs().edit().putBoolean("provider_validation_tmdb",true).apply();}catch(Exception e){messages.add("TMDB: "+safe(e,tk));}if(!os.isEmpty())try{OpenSubtitlesClient client=new OpenSubtitlesClient(os);List<OpenSubtitlesClient.SubtitleFile> files=client.search("","tt1375666","ar",0,0);if(files.isEmpty())throw new java.io.IOException("No validation subtitle available");if(SubtitleParser.parse(client.fetch(client.download(files.get(0).id))).isEmpty())throw new java.io.IOException("No valid downloaded subtitle cues");validOs=os;messages.add("OpenSubtitles: ✓");prefs().edit().putBoolean("provider_validation_os",true).apply();}catch(Exception e){messages.add("OpenSubtitles: "+safe(e,os));}if(!ss.isEmpty())try{new SubsourceClient(ss).validate();validSub=ss;messages.add("Subsource: ✓");prefs().edit().putBoolean("provider_validation_sub",true).apply();}catch(Exception e){messages.add("Subsource: "+safe(e,ss));}if(closed||Thread.currentThread().isInterrupted())return;if(!validOs.isEmpty()||!validSub.isEmpty()||!validTmdb.isEmpty())new ProviderSecrets(validOs,validSub,validTmdb).save(this);final String message=String.join("\n",messages)+"\n"+tx("حُفظت المفاتيح الصالحة مشفّرة على التلفزيون.","Valid keys saved encrypted on this TV.");runOnUiThread(()->{if(closed)return;open.setText("");sub.setText("");tmdb.setText("");status.setText(message);save.setEnabled(true);});}catch(Exception e){runOnUiThread(()->{if(!closed){status.setText(tx("تعذر حفظ الإعدادات المشفرة","Could not save encrypted settings"));save.setEnabled(true);}});}});}
 private static String safe(Exception e,String key){String m=String.valueOf(e.getMessage());return key.isEmpty()?m:m.replace(key,"[redacted]");}
 @Override protected void onDestroy(){closed=true;io.shutdownNow();super.onDestroy();}
}
